func TestRasterDocumentFusesTheFramesTracedRules(emonT *testing.T) {
	var c *enctx.Cfg = enctx.NewCfg()
	var d *enctx.Doc = enctx.NewDoc()
	var ev *enctx.EvArenas = enctx.NewEvArenas()
	var m *enctx.Arenas = enctx.NewArenas()
	var s *enctx.Scratch = enctx.NewScratch()
	config.CfParse(port.NewCells(), c)
	model.ModelInit(m.Nodes, m.Attrs, m.Regions, m.Text, m.Pages, m.Ledger, m.Layout)
	model.PageNew(m.Pages, 1, 30000, 40000, 0, model.PkImage())
	evidence.EpNew(ev.Epages, 1, 30000, 40000)
	evidence.EpSet(ev.Epages, 0, evidence.EpfFlags(), evidence.EgRaster())
	evidence.RlNew(ev.Rules, 1, 1000, 1950, 29000, 2050, 0)
	evidence.RlSet(ev.Rules, 0, evidence.RlfLx0(), 1000)
	evidence.RlSet(ev.Rules, 0, evidence.RlfLy0(), 2000)
	evidence.RlSet(ev.Rules, 0, evidence.RlfLx1(), 29000)
	evidence.RlSet(ev.Rules, 0, evidence.RlfLy1(), 2000)
	evidence.RlSet(ev.Rules, 0, evidence.RlfThick(), 100)
	evidence.RlSet(ev.Rules, 0, evidence.RlfColor(), 13421772)
	evidence.RlSet(ev.Rules, 0, evidence.RlfConf(), 1000)
	port.AssertEq(emonT, engine.EnFinishRaster(c, d, ev, m, s), 0, "the empty frame finishes")
	port.AssertEq(emonT, glayer.GrlCount(d.Grl), 1, "the frame's light rule reaches the table stage")
}

