	evidence.RlSet(ev.Rules, 0, evidence.RlfColor(), 13421772)
	evidence.RlSet(ev.Rules, 0, evidence.RlfConf(), 1000)
	evidence.RlNew(ev.Rules, 1, 1000, 10000, 1600, 10060, 0)
	evidence.RlSet(ev.Rules, 1, evidence.RlfLx0(), 1000)
	evidence.RlSet(ev.Rules, 1, evidence.RlfLy0(), 10000)
	evidence.RlSet(ev.Rules, 1, evidence.RlfLx1(), 1600)
	evidence.RlSet(ev.Rules, 1, evidence.RlfLy1(), 10060)
